<header class="page-header"><p class="eyebrow">Writing</p><h1><?= e($title) ?></h1><p><?= e($description) ?></p><form class="search" action="<?= e(url('search')) ?>"><label class="sr-only" for="q">Search articles</label><input id="q" name="q" value="<?= e($query) ?>" maxlength="100" placeholder="Search articles…"><button class="button">Search</button></form></header>
<div class="post-list"><?php if(!$pagination['items']):?><div class="empty"><h2>No posts found</h2><p>Try another search or return later.</p></div><?php endif?><?php foreach($pagination['items'] as $item):?><article class="post-card"><p class="meta"><?= e(date('M j, Y',strtotime($item['published_at']))) ?><?php if($item['category_name']):?> · <?= e($item['category_name']) ?><?php endif?></p><h2><a href="<?= e(url('blog/'.$item['slug'])) ?>"><?= e($item['title']) ?></a></h2><p><?= e($item['excerpt']) ?></p><a class="read-more" href="<?= e(url('blog/'.$item['slug'])) ?>">Read article →</a></article><?php endforeach?></div>
<?php if($pagination['pages']>1):?><nav class="pagination" aria-label="Pagination"><?php for($i=1;$i<=$pagination['pages'];$i++):?><a <?= $i===$pagination['page']?'aria-current="page"':'' ?> href="<?= e(url($i===1?'blog':'blog/page/'.$i).($query?'?q='.rawurlencode($query):'')) ?>"><?= $i ?></a><?php endfor?></nav><?php endif?>
